import 'package:flutter/material.dart'; import '../../services/vault_service.dart';
class VaultScreen extends StatefulWidget { const VaultScreen({super.key}); @override State<VaultScreen> createState()=>_VaultState(); }
class _VaultState extends State<VaultScreen>{final service=VaultService();final pin=TextEditingController();bool unlocked=false;String? error;
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Private vault')),body:unlocked?const Center(child:Text('Vault unlocked. Hidden media is stored in the local encrypted app area.')):Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[const Icon(Icons.lock,size:64),TextField(controller:pin,keyboardType:TextInputType.number,obscureText:true,decoration:InputDecoration(labelText:'Vault PIN',errorText:error)),const SizedBox(height:12),FilledButton(onPressed:()async{if(await service.hasPin()){final ok=await service.unlock(pin.text);setState((){unlocked=ok;error=ok?null:'Incorrect PIN';});}else{await service.setPin(pin.text);setState(()=>unlocked=true);}},child:const Text('Unlock / create vault'))])));}
